'use strict';
const $=(s)=>document.querySelector(s);
const services={muffler:{title:'MUFFLER REPAIR.',name:'Muffler repair',description:'A muffler concern can change how every drive feels. Call R & K Muffler to discuss repair or replacement for your vehicle.',items:['Your vehicle’s year, make, and model','When the sound changed and where it seems to come from','Any visible damage or recent exhaust work']},converter:{title:'CATALYTIC CONVERTERS.',name:'Catalytic converter service',description:'R & K Muffler repairs catalytic converters. Contact the shop about your vehicle and discuss inspection, repair, or replacement options.',items:['Your vehicle’s year, make, and model','Any warning lights or diagnostic codes you already have','Whether you are asking about a repair or a missing converter']},exhaust:{title:'EXHAUST SERVICE.',name:'Exhaust service',description:'Have an exhaust rattle, a pipe concern, or a suspected leak? Describe what you are noticing so the shop can discuss the next step.',items:['The noise or concern and when you first noticed it','Whether it happens at idle, while accelerating, or over bumps','Any previous exhaust repairs or modifications']}};
const menu=$('.menu');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');$('#navigation').classList.toggle('open',open)});
$('#navigation').addEventListener('click',e=>{if(e.target.closest('a')){menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');$('#navigation').classList.remove('open')}});
window.addEventListener('keydown',e=>{if(e.key==='Escape'){menu.setAttribute('aria-expanded','false');$('#navigation').classList.remove('open')}});
let lastFocus=null;
function openDialog(dialog){lastFocus=document.activeElement;dialog.showModal();document.body.classList.add('modal-open')}
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});d.addEventListener('close',()=>{if(!document.querySelector('dialog[open]')){document.body.classList.remove('modal-open');if(lastFocus?.isConnected)lastFocus.focus()}if(d.id==='planner'){resetPlanner();$('#planner-form').reset();$('#call-summary').textContent=''}})});
let selectedService='Not sure yet';
document.querySelectorAll('[data-service]').forEach(b=>b.addEventListener('click',()=>{const s=services[b.dataset.service];selectedService=s.name;$('#service-title').textContent=s.title;$('#service-description').textContent=s.description;$('#service-list').replaceChildren(...s.items.map(t=>{const li=document.createElement('li');li.textContent=t;return li}));openDialog($('#service-dialog'))}));
function resetPlanner(){$('#planner-form').hidden=false;$('#plan-result').hidden=true;$('#planner-title').textContent='LET’S GET READY.'}
function openPlanner(service){resetPlanner();$('#plan-service').value=service;openDialog($('#planner'))}
document.querySelectorAll('[data-plan]').forEach(b=>b.addEventListener('click',()=>openPlanner(b.dataset.plan)));
$('#service-plan').addEventListener('click',()=>{$('#service-dialog').close();openPlanner(selectedService)});
const currentYear=new Date().getFullYear();$('#year').textContent=currentYear;$('#vehicle-year').max=currentYear+2;
$('#planner-form').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;for(const input of form.querySelectorAll('input[name=make],input[name=model]')){input.value=input.value.trim();if(!input.value){input.reportValidity();return}}if(!form.reportValidity())return;const data=new FormData(form);const notes=String(data.get('notes')).trim();$('#call-summary').textContent=`R & K Muffler — call notes\n\nService: ${data.get('service')}\nVehicle: ${data.get('year')} ${data.get('make')} ${data.get('model')}${notes?'\nConcern: '+notes:''}\n\nAsk about availability, inspection, pricing, and timing.\nPhone: (310) 691-9772\n4623 Artesia Blvd, Unit 4, Lawndale, CA 90260`;form.hidden=true;$('#plan-result').hidden=false;$('#planner-title').textContent='YOU’RE READY TO CALL.';$('#planner').scrollTop=0;$('#plan-result a').focus()});
$('#edit-plan').addEventListener('click',()=>{resetPlanner();$('#plan-service').focus()});
let toastTimeout;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.')}catch{const t=document.createElement('textarea');t.value=text;t.style.position='fixed';t.style.opacity='0';const parent=document.querySelector('dialog[open]')||document.body;parent.appendChild(t);t.select();let ok=false;try{ok=document.execCommand('copy')}catch{}t.remove();toast(ok?'Copied to clipboard.':'Could not copy automatically. Please select and copy the text.')}}
$('#copy-summary').addEventListener('click',()=>copy($('#call-summary').textContent));$('#copy-address').addEventListener('click',()=>copy('R & K Muffler, 4623 Artesia Blvd Unit 4, Lawndale, CA 90260'));$('#privacy-open').addEventListener('click',()=>openDialog($('#privacy')));
